const tone=(s:string)=>s.includes("Dostupno")||s.includes("Plaćeno")||s.includes("Aktivan")?"green":s.includes("Iznajmljeno")||s.includes("Aktivna")||s.includes("U toku")?"blue":s.includes("Povrat")||s.includes("servisu")||s.includes("Uskoro")?"red":s.includes("Potvr")||s.includes("Rezervisano")?"violet":"amber";
function Badge({s}:{s:string}){return <span className={`badge ${tone(s)}`}><i/>{s}</span>}
function Head({title,sub,action,onAction}:{title:string;sub:string;action?:string;onAction?:()=>void}){return <div className="page-title"><div><h1>{title}</h1><small>{sub}</small></div>{action&&<button className="primary standalone" onClick={onAction}>+ {action}</button>}</div>}
function Kpis({items,actions}:{items:string[][];actions?:Array<()=>void>}){return <div className="kpi-grid">{items.map((x,i)=><article className={`kpi ${actions?.[i]?"clickable":""}`} key={x[0]} onClick={actions?.[i]} tabIndex={actions?.[i]?0:undefined} onKeyDown={e=>{if(actions?.[i]&&(e.key==="Enter"||e.key===" "))actions[i]()}}><div className={`kpi-icon ${x[4]}`}>◇</div><span>{x[0]}</span><strong>{x[1]}</strong><footer><small>{x[2]}</small><b className={x[4]}>{x[3]}</b></footer></article>)}</div>}
const fleetKpis=[["Ukupno vozila","24","u 3 poslovnice","+2","blue"],["Dostupno","6","spremno za najam","25%","green"],["Iznajmljeno","14","trenutno na putu","58%","violet"],["Na servisu","3","1 završava danas","12%","red"],["Prosečna starost","2,8 god","prosek flote","-0,3","cyan"],["Vrednost flote","68,4M RSD","procena","+4,1%","amber"]];
function Dashboard({go,openBooking,newReservation,addVehicle}:{go:(x:string)=>void;openBooking:(b:B)=>void;newReservation:()=>void;addVehicle:()=>void}){const[period,setPeriod]=useState(30);const periodData:Record<number,[string,string]>={7:["684.200 RSD","+6,2%"],30:["2.847.500 RSD","+12,8%"],90:["8.164.300 RSD","+18,4%"]};const changePeriod=(e:React.MouseEvent)=>{e.stopPropagation();setPeriod(p=>p===7?30:p===30?90:7)};return <><div className="page-title"><div><p>PONEDELJAK, 24. AVGUST</p><h1>Dobro jutro, Marko 👋</h1><small>Evo šta se danas dešava sa vašom flotom.</small></div></div><Kpis items={[["Aktivna vozila","18","od 24 ukupno","+2 ovaj mesec","blue"],["Današnji prihod","184.500 RSD","12 rezervacija","+8,4%","green"],["Iskorišćenost","78%","prosek flote","+4,2%","violet"],["Povrat danas","5","2 kasne","Do 18:00","amber"],["Servis uskoro","3","u narednih 7 dana","Pogledaj","red"],["Nove rezervacije","9","poslednja 24h","+3 danas","cyan"]]} actions={[()=>go("Vozila"),()=>go("Finansije"),()=>go("Izveštaji"),()=>go("Rezervacije"),()=>go("Servisi i registracije"),()=>go("Rezervacije")]}/><div className="dashboard-grid"><section className="panel revenue dashboard-link" onClick={()=>go("Finansije")}><div className="panel-head"><div><h2>Prihod</h2><p>Poslednjih {period} dana</p></div><button onClick={changePeriod}>{period} dana ⌄</button></div><div className="revenue-stat"><strong>{periodData[period][0]}</strong><span>{periodData[period][1]}</span></div><div className="line-chart"><div className="chart-fill"/></div><div className="chart-labels static"><span>Početak</span><span>1. nedelja</span><span>2. nedelja</span><span>3. nedelja</span><span>Danas</span></div></section><section className="panel activities"><div className="panel-head"><div><h2>Današnje aktivnosti</h2><p>8 aktivnosti</p></div><a onClick={()=>go("Rezervacije")}>Vidi sve</a></div>{bookings.slice(0,4).map((b,i)=><div className="activity dashboard-link" key={b.id} onClick={()=>openBooking(b)}><b>{b.from.split("•")[1]}</b><i className={i%2?"green":"blue"}/><div><span>{i%2?"Vraćanje":"Preuzimanje"}</span><strong>{b.client}</strong><small>{b.vehicle}</small></div></div>)}</section></div><div className="dashboard-lower"><section className="panel"><div className="panel-head"><div><h2>Današnje rezervacije</h2><p>5 preuzimanja i povrata</p></div><a onClick={()=>go("Rezervacije")}>Sve rezervacije</a></div>{bookings.slice(0,3).map(b=><div className="mini-row dashboard-link" key={b.id} onClick={()=>openBooking(b)}><div className="avatar">{b.client.split(" ").map(x=>x[0]).join("")}</div><div><strong>{b.client}</strong><small>{b.vehicle}</small></div><Badge s={b.status}/><b>{b.from.split("•")[1]}</b></div>)}</section><section className="panel notice-panel"><div className="panel-head"><div><h2>Obaveštenja</h2><p>Zahtevaju pažnju</p></div></div>{[["Registracija ističe","BMW 320d • za 6 dana","red","Servisi i registracije"],["Redovan servis","Golf 7 • za 2.760 km","amber","Servisi i registracije"],["Kašnjenje povrata","DN-2832 • 1h 24min","violet","Rezervacije"]].map(n=><div className="notice dashboard-link" key={n[0]} onClick={()=>go(n[3])}><i className={n[2]}>◇</i><div><strong>{n[0]}</strong><small>{n[1]}</small></div><span>›</span></div>)}</section><section className="panel quick"><div className="panel-head"><div><h2>Brze akcije</h2><p>Najčešće radnje</p></div></div><button onClick={newReservation}><b>+</b>Nova rezervacija</button><button onClick={addVehicle}><b>◇</b>Dodaj vozilo</button><button onClick={()=>go("Klijenti")}><b>◉</b>Novi klijent</button></section></div></>}
function Toolbar({q,setQ}:{q:string;setQ:(x:string)=>void}){return <div className="toolbar"><div className="table-search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Pretraži..."/></div><select><option>Svi statusi</option><option>Dostupno</option><option>Iznajmljeno</option></select><button>Više filtera ☷</button></div>}
function Vehicles({open,addTrigger=0}:{open:(v:V)=>void;addTrigger?:number}){const[q,setQ]=useState("");const[status,setStatus]=useState("Svi statusi");const[location,setLocation]=useState("Sve lokacije");const[more,setMore]=useState(false);const[sortNew,setSortNew]=useState(false);const[added,setAdded]=useState<V[]>([]);const[showAdd,setShowAdd]=useState(addTrigger>0);const[loading,setLoading]=useState(true);useEffect(()=>{fetch("/api/vehicles").then(r=>r.ok?r.json():Promise.reject()).then(data=>setAdded((data.vehicles||[]).map((v:V&{km:number})=>({...v,km:`${Number(v.km).toLocaleString("sr-RS")} km`})))).finally(()=>setLoading(false))},[]);useEffect(()=>{if(addTrigger>0)setShowAdd(true)},[addTrigger]);const all=[...added,...vehicles].filter((v,i,a)=>a.findIndex(x=>x.plate===v.plate)===i);const shown=all.filter(v=>(v.name+v.plate+v.location).toLowerCase().includes(q.toLowerCase())&&(status==="Svi statusi"||v.status===status)&&(location==="Sve lokacije"||v.location.startsWith(location))).sort((a,b)=>sortNew?b.year-a.year:0);const setKpi=(s:string)=>{setStatus(s);setSortNew(false)};return <><Head title="Vozila" sub="Pregled i upravljanje kompletnom flotom." action="Dodaj vozilo" onAction={()=>setShowAdd(true)}/><Kpis items={fleetKpis} actions={[()=>setKpi("Svi statusi"),()=>setKpi("Dostupno"),()=>setKpi("Iznajmljeno"),()=>setKpi("Na servisu"),()=>{setStatus("Svi statusi");setSortNew(true)},()=>setKpi("Svi statusi")]}/><section className="panel table-panel"><div className="toolbar"><div className="table-search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Marka, model, tablice ili lokacija..."/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option>Svi statusi</option><option>Dostupno</option><option>Iznajmljeno</option><option>Rezervisano</option><option>Na servisu</option></select><button className={more?"filter-active":""} onClick={()=>setMore(x=>!x)}>Više filtera ☷</button></div>{more&&<div className="advanced-filters"><label>Lokacija<select value={location} onChange={e=>setLocation(e.target.value)}><option>Sve lokacije</option><option>Beograd</option><option>Novi Sad</option><option>Niš</option></select></label><label><input type="checkbox" checked={sortNew} onChange={e=>setSortNew(e.target.checked)}/> Najnovija vozila prvo</label><button onClick={()=>{setQ("");setStatus("Svi statusi");setLocation("Sve lokacije");setSortNew(false)}}>Očisti filtere</button></div>}<div className="active-filter-note">Prikazano {shown.length} od {all.length} vozila{status!=="Svi statusi"?` • ${status}`:""}</div><div className="table-scroll"><table><thead><tr><th>VOZILO</th><th>STATUS</th><th>KILOMETRAŽA</th><th>LOKACIJA</th><th>SLEDEĆI SERVIS</th><th/></tr></thead><tbody>{shown.map(v=><tr key={v.plate} onClick={()=>open(v)}><td><div className="vehicle-cell"><span className="car-thumb">▰</span><div><strong>{v.name}</strong><small>{v.year} • {v.plate}</small></div></div></td><td><Badge s={v.status}/></td><td>{v.km}</td><td>{v.location}</td><td>{v.service}</td><td><button className="row-action" onClick={e=>{e.stopPropagation();open(v)}} aria-label={`Detalji ${v.name}`}>⋯</button></td></tr>)}</tbody></table>{!loading&&!shown.length&&<div className="empty-table">Nema vozila koja odgovaraju izabranim filterima.</div>}{loading&&<div className="vehicle-loading">Učitavanje sačuvanih vozila…</div>}</div></section>{showAdd&&<AddVehicleModal existing={all} close={()=>setShowAdd(false)} added={v=>{setAdded(x=>[v,...x]);setShowAdd(false)}}/>}</>}
function AddVehicleModal({existing,close,added}:{existing:V[];close:()=>void;added:(v:V)=>void}){const[form,setForm]=useState({name:"",plate:"",year:"2026",km:"0",location:"Beograd • Aerodrom",status:"Dostupno",service:"Nije zakazano"});const[error,setError]=useState("");const[saving,setSaving]=useState(false);const set=(key:string,value:string)=>setForm(f=>({...f,[key]:value}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setError("");if(existing.some(v=>v.plate.replace(/\s/g,"").toLowerCase()===form.plate.replace(/\s/g,"").toLowerCase())){setError("Vozilo sa ovim registarskim tablicama već postoji.");return}setSaving(true);try{const response=await fetch("/api/vehicles",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,year:Number(form.year),km:Number(form.km)})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Vozilo nije sačuvano.");added({...data.vehicle,km:`${Number(data.vehicle.km).toLocaleString("sr-RS")} km`})}catch(e){setError(e instanceof Error?e.message:"Vozilo nije sačuvano.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer add-vehicle" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close} aria-label="Zatvori">×</button><small>NOVO VOZILO</small><h2>Dodaj vozilo u flotu</h2><p className="drawer-intro">Unesite osnovne podatke. Vozilo će odmah biti sačuvano i prikazano u tabeli.</p><form onSubmit={submit}><label>Marka i model *<input required value={form.name} onChange={e=>set("name",e.target.value)} placeholder="npr. Volkswagen Passat"/></label><div className="add-form-grid"><label>Registarske tablice *<input required value={form.plate} onChange={e=>set("plate",e.target.value.toUpperCase())} placeholder="BG 1234-AA"/></label><label>Godište *<input required type="number" min="1990" max="2027" value={form.year} onChange={e=>set("year",e.target.value)}/></label><label>Kilometraža *<input required type="number" min="0" value={form.km} onChange={e=>set("km",e.target.value)}/></label><label>Lokacija *<select value={form.location} onChange={e=>set("location",e.target.value)}><option>Beograd • Aerodrom</option><option>Beograd • Novi Beograd</option><option>Beograd • Dorćol</option><option>Novi Sad • Centar</option><option>Novi Sad • Stanica</option><option>Niš • Aerodrom</option></select></label><label>Status *<select value={form.status} onChange={e=>set("status",e.target.value)}><option>Dostupno</option><option>Rezervisano</option><option>Iznajmljeno</option><option>Na servisu</option></select></label><label>Sledeći servis<input value={form.service} onChange={e=>set("service",e.target.value)} placeholder="npr. 12. okt 2026"/></label></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="outline" onClick={close}>Otkaži</button><button className="primary" disabled={saving}>{saving?"Čuvanje…":"Dodaj vozilo"}</button></div></form></aside></div>}
function VehicleDetail({v,back}:{v:V;back:()=>void}){const[current,setCurrent]=useState(v);const[tab,setTab]=useState("Pregled");const[edit,setEdit]=useState(false);const tabs=["Pregled","Dokumentacija","Servisi","Troškovi","Rezervacije","Štete"];return <><button className="back" onClick={back}>← Sva vozila</button><div className="detail-head"><div className="big-car">▰</div><div><Badge s={current.status}/><h1>{current.name}</h1><p>{current.year} • {current.plate}</p></div><button className="outline" onClick={()=>setEdit(true)}>Uredi vozilo</button></div><div className="detail-tabs">{tabs.map(x=><button key={x} className={tab===x?"active":""} onClick={()=>setTab(x)}>{x}</button>)}</div>{tab==="Pregled"?<div className="detail-grid"><section className="panel info-card"><h2>Osnovni podaci</h2>{[["Registracija",current.plate],["VIN","WVWZZZAUZLW084321"],["Kilometraža",current.km],["Gorivo","Dizel"],["Menjač","Automatski"],["Lokacija",current.location]].map(x=><div key={x[0]}><small>{x[0]}</small><b>{x[1]}</b></div>)}</section><section className="panel health"><h2>Status vozila</h2><div className="fuel"><span>Gorivo</span><b>72%</b><i><em/></i></div><div className="health-stats"><div><small>Poslednji servis</small><b>12. avg 2026</b></div><div><small>Sledeći servis</small><b>{current.service}</b></div><div><small>Registracija važi do</small><b>18. feb 2027</b></div></div></section><section className="panel timeline"><h2>Poslednje aktivnosti</h2>{[["24. avg","Preuzimanje vozila","Miloš Jovanović • DN-2841"],["21. avg","Vozilo vraćeno","Gorivo 88% • Bez novih oštećenja"],["12. avg","Redovan servis","Auto Centar Beograd • 24.600 RSD"]].map(x=><div key={x[0]}><i/><small>{x[0]}</small><strong>{x[1]}</strong><p>{x[2]}</p></div>)}</section></div>:<VehicleTab tab={tab} v={current}/>} {edit&&<EditVehicleModal vehicle={current} close={()=>setEdit(false)} saved={x=>{setCurrent(x);setEdit(false)}}/>}</>}
function VehicleTab({tab,v}:{tab:string;v:V}){const data:Record<string,string[][]>={"Dokumentacija":[["Saobraćajna dozvola","Važi do 18. feb 2027"],["Polisa osiguranja","Važi do 18. feb 2027"],["Kasko polisa","Važi do 02. mar 2027"]],"Servisi":[["Redovan servis","12. avg 2026 • 24.600 RSD"],["Zamena pneumatika","18. apr 2026 • 42.000 RSD"],["Tehnički pregled","02. feb 2026 • 6.500 RSD"]],"Troškovi":[["Servisi","96.400 RSD"],["Registracija i osiguranje","118.200 RSD"],["Pranje i priprema","34.800 RSD"]],"Rezervacije":[["DN-2841 • Miloš Jovanović","24–28. avg 2026"],["DN-2798 • Ivana Popović","12–16. avg 2026"],["DN-2741 • Petar Đorđević","02–07. avg 2026"]],"Štete":[["Ogrebotina — zadnji branik","Sanirano • 18.500 RSD"],["Ulubljenje — leva vrata","Sanirano • 32.000 RSD"]]};return <section className="panel vehicle-tab-panel"><div className="panel-head"><div><h2>{tab}</h2><p>{v.name} • {v.plate}</p></div><button className="outline">+ Dodaj zapis</button></div>{(data[tab]||[]).map((x,i)=><button className="vehicle-record" key={i}><span>□</span><div><strong>{x[0]}</strong><small>{x[1]}</small></div><i>›</i></button>)}</section>}
function EditVehicleModal({vehicle,close,saved}:{vehicle:V;close:()=>void;saved:(v:V)=>void}){const[form,setForm]=useState({...vehicle,km:vehicle.km.replace(/[^0-9]/g,"")});const[error,setError]=useState("");const[saving,setSaving]=useState(false);const set=(k:string,value:string)=>setForm(f=>({...f,[k]:value}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setSaving(true);setError("");try{const r=await fetch("/api/vehicles",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,originalPlate:vehicle.plate,year:Number(form.year),km:Number(form.km)})});const data=await r.json();if(!r.ok)throw new Error(data.error||"Vozilo nije izmenjeno.");saved({...data.vehicle,km:`${Number(data.vehicle.km).toLocaleString("sr-RS")} km`})}catch(e){setError(e instanceof Error?e.message:"Vozilo nije izmenjeno.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer add-vehicle" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>UREĐIVANJE VOZILA</small><h2>{vehicle.name}</h2><form onSubmit={submit}><label>Marka i model<input required value={form.name} onChange={e=>set("name",e.target.value)}/></label><div className="add-form-grid"><label>Tablice<input required value={form.plate} onChange={e=>set("plate",e.target.value.toUpperCase())}/></label><label>Godište<input required type="number" value={form.year} onChange={e=>set("year",e.target.value)}/></label><label>Kilometraža<input required type="number" value={form.km} onChange={e=>set("km",e.target.value)}/></label><label>Lokacija<select value={form.location} onChange={e=>set("location",e.target.value)}><option>Beograd • Aerodrom</option><option>Beograd • Novi Beograd</option><option>Beograd • Dorćol</option><option>Novi Sad • Centar</option><option>Niš • Aerodrom</option></select></label><label>Status<select value={form.status} onChange={e=>set("status",e.target.value)}><option>Dostupno</option><option>Iznajmljeno</option><option>Rezervisano</option><option>Na servisu</option></select></label><label>Sledeći servis<input value={form.service} onChange={e=>set("service",e.target.value)}/></label></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="outline" onClick={close}>Otkaži</button><button className="primary" disabled={saving}>{saving?"Čuvanje…":"Sačuvaj izmene"}</button></div></form></aside></div>}
function Reservations({open,newReservation,refresh,overrides}:{open:(b:B)=>void;newReservation:()=>void;refresh:number;overrides:Record<string,string>}){const[q,setQ]=useState("");const[status,setStatus]=useState("Svi statusi");const[vehicle,setVehicle]=useState("Sva vozila");const[more,setMore]=useState(false);const[sortValue,setSortValue]=useState(false);const[added,setAdded]=useState<B[]>([]);const[loading,setLoading]=useState(true);useEffect(()=>{setLoading(true);fetch("/api/reservations").then(r=>r.ok?r.json():Promise.reject()).then(data=>setAdded((data.reservations||[]).map((r:{code:string;client:string;vehicle:string;startsAt:string;endsAt:string;price:number;status:string})=>({id:r.code,client:r.client,vehicle:r.vehicle,from:formatDate(r.startsAt),to:formatDate(r.endsAt),price:`${Number(r.price).toLocaleString("sr-RS")} RSD`,status:r.status})))).catch(()=>{}).finally(()=>setLoading(false))},[refresh]);const all=[...added,...bookings].filter((b,i,a)=>a.findIndex(x=>x.id===b.id)===i).map(b=>({...b,status:overrides[b.id]||b.status}));const shown=all.filter(b=>(b.client+b.vehicle+b.id).toLowerCase().includes(q.toLowerCase())&&(status==="Svi statusi"||b.status===status)&&(vehicle==="Sva vozila"||b.vehicle===vehicle)).sort((a,b)=>sortValue?Number(b.price.replace(/\D/g,""))-Number(a.price.replace(/\D/g,"")):0);const setKpi=(s:string)=>{setStatus(s);setSortValue(false)};const clear=()=>{setQ("");setStatus("Svi statusi");setVehicle("Sva vozila");setSortValue(false)};return <><Head title="Rezervacije" sub="Sve rezervacije, preuzimanja i povrati na jednom mestu." action="Nova rezervacija" onAction={newReservation}/><Kpis items={[["Danas","12","5 preuzimanja","+3","blue"],["Aktivne","18","trenutno u najmu","+2","green"],["Predstojeće","31","narednih 7 dana","+12%","violet"],["Povrat danas","5","2 kasne","Do 18h","red"],["Na čekanju","4","zahteva potvrdu","4","amber"],["Vrednost","1,24M RSD","aktivne rezervacije","+9,3%","cyan"]]} actions={[()=>setKpi("Svi statusi"),()=>setKpi("Aktivna"),()=>setKpi("Potvrđena"),()=>setKpi("Povrat danas"),()=>setKpi("Na čekanju"),()=>{setStatus("Svi statusi");setSortValue(true)}]}/><section className="panel table-panel"><div className="toolbar"><div className="table-search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Broj rezervacije, klijent ili vozilo..."/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option>Svi statusi</option><option>Na čekanju</option><option>Potvrđena</option><option>Aktivna</option><option>Povrat danas</option><option>Završena</option><option>Otkazana</option></select><button className={more?"filter-active":""} onClick={()=>setMore(x=>!x)}>Više filtera ☷</button></div>{more&&<div className="advanced-filters"><label>Vozilo<select value={vehicle} onChange={e=>setVehicle(e.target.value)}><option>Sva vozila</option>{[...new Set(all.map(b=>b.vehicle))].map(v=><option key={v}>{v}</option>)}</select></label><label><input type="checkbox" checked={sortValue} onChange={e=>setSortValue(e.target.checked)}/> Najveća vrednost prvo</label><button onClick={clear}>Očisti filtere</button></div>}<div className="active-filter-note">Prikazano {shown.length} od {all.length} rezervacija{status!=="Svi statusi"?` • ${status}`:""}</div><div className="table-scroll"><table><thead><tr><th>REZERVACIJA</th><th>KLIJENT</th><th>VOZILO</th><th>PERIOD</th><th>CENA</th><th>STATUS</th><th/></tr></thead><tbody>{shown.map(b=><tr key={b.id} onClick={()=>open(b)}><td><strong className="link">{b.id}</strong></td><td>{b.client}</td><td>{b.vehicle}</td><td><strong>{b.from}</strong><small>do {b.to}</small></td><td><strong>{b.price}</strong><small>Plaćeno karticom</small></td><td><Badge s={b.status}/></td><td><button className="row-action" onClick={e=>{e.stopPropagation();open(b)}} aria-label={`Otvori ${b.id}`}>⋯</button></td></tr>)}</tbody></table>{!loading&&!shown.length&&<div className="empty-table">Nema rezervacija koje odgovaraju izabranim filterima.</div>}{loading&&<div className="vehicle-loading">Učitavanje sačuvanih rezervacija…</div>}</div></section></>}
const formatDate=(value:string)=>{const d=new Date(value);return Number.isFinite(d.getTime())?`${d.toLocaleDateString("sr-RS",{day:"2-digit",month:"short"})} • ${d.toLocaleTimeString("sr-RS",{hour:"2-digit",minute:"2-digit"})}`:value};
function NewReservationModal({close,saved}:{close:()=>void;saved:()=>void}){const[vehicleOptions,setVehicleOptions]=useState(vehicles.map(v=>v.name));const[form,setForm]=useState({client:"",vehicle:vehicles[0].name,startsAt:"",endsAt:"",location:"Beograd • Aerodrom",price:"",status:"Potvrđena"});const[error,setError]=useState("");const[saving,setSaving]=useState(false);useEffect(()=>{fetch("/api/vehicles").then(r=>r.ok?r.json():Promise.reject()).then(data=>setVehicleOptions([...new Set([...(data.vehicles||[]).map((v:{name:string})=>v.name),...vehicles.map(v=>v.name)])])).catch(()=>{})},[]);const set=(key:string,value:string)=>setForm(f=>({...f,[key]:value}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setError("");if(new Date(form.endsAt)<=new Date(form.startsAt)){setError("Datum vraćanja mora biti posle datuma preuzimanja.");return}setSaving(true);try{const response=await fetch("/api/reservations",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,price:Number(form.price)})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Rezervacija nije sačuvana.");saved()}catch(e){setError(e instanceof Error?e.message:"Rezervacija nije sačuvana.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer add-vehicle reservation-form" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close} aria-label="Zatvori">×</button><small>NOVA REZERVACIJA</small><h2>Kreiraj rezervaciju</h2><p className="drawer-intro">Unesite klijenta, vozilo i period najma. Rezervacija će biti trajno sačuvana.</p><form onSubmit={submit}><label>Ime i prezime klijenta *<input required value={form.client} onChange={e=>set("client",e.target.value)} placeholder="npr. Petar Petrović"/></label><label>Vozilo *<select value={form.vehicle} onChange={e=>set("vehicle",e.target.value)}>{vehicleOptions.map(v=><option key={v}>{v}</option>)}</select></label><div className="add-form-grid"><label>Preuzimanje *<input required type="datetime-local" value={form.startsAt} onChange={e=>set("startsAt",e.target.value)}/></label><label>Vraćanje *<input required type="datetime-local" value={form.endsAt} onChange={e=>set("endsAt",e.target.value)}/></label><label>Lokacija *<select value={form.location} onChange={e=>set("location",e.target.value)}><option>Beograd • Aerodrom</option><option>Beograd • Novi Beograd</option><option>Beograd • Dorćol</option><option>Novi Sad • Centar</option><option>Novi Sad • Stanica</option><option>Niš • Aerodrom</option></select></label><label>Cena (RSD) *<input required type="number" min="0" step="100" value={form.price} onChange={e=>set("price",e.target.value)} placeholder="45000"/></label><label>Status *<select value={form.status} onChange={e=>set("status",e.target.value)}><option>Na čekanju</option><option>Potvrđena</option><option>Aktivna</option></select></label></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="outline" onClick={close}>Otkaži</button><button className="primary" disabled={saving}>{saving?"Čuvanje…":"Kreiraj rezervaciju"}</button></div></form></aside></div>}
function BookingPanel({b,close,saved}:{b:B;close:()=>void;saved:(id:string,status:string)=>void}){const[s,setS]=useState(b.status);const[saving,setSaving]=useState(false);const[error,setError]=useState("");const download=(kind:string)=>{const content=`DriveNode Fleet Manager\n${kind}\nRezervacija: ${b.id}\nKlijent: ${b.client}\nVozilo: ${b.vehicle}\nPeriod: ${b.from} — ${b.to}\nStatus: ${s}\nVrednost: ${b.price}`;const url=URL.createObjectURL(new Blob([content],{type:"text/plain;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=`${kind.replace(/\s/g,"_")}_${b.id}.txt`;a.click();URL.revokeObjectURL(url)};const save=async()=>{setSaving(true);setError("");try{const r=await fetch("/api/reservations",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({code:b.id,status:s})});const data=await r.json();if(!r.ok)throw new Error(data.error||"Status nije sačuvan.");saved(b.id,s)}catch(e){setError(e instanceof Error?e.message:"Status nije sačuvan.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>REZERVACIJA {b.id}</small><h2>{b.client}</h2><Badge s={s}/><div className="booking-car"><div className="big-car">▰</div><div><b>{b.vehicle}</b><small>Rent-a-car vozilo</small></div></div><div className="trip"><div><small>PREUZIMANJE</small><b>{b.from}</b><span>Beograd</span></div><i>→</i><div><small>VRAĆANJE</small><b>{b.to}</b><span>Beograd</span></div></div><section><h3>Plaćanje</h3><div className="price-row"><span>Najam vozila</span><b>{b.price}</b></div><div className="price-row"><span>Depozit</span><b>30.000 RSD</b></div></section><section><h3>Dokumenta</h3><button className="doc-row" onClick={()=>download("Ugovor o najmu")}>□ Ugovor o najmu <span>TXT ↓</span></button><button className="doc-row" onClick={()=>download("Podaci vozačke dozvole")}>□ Podaci vozačke dozvole <span>TXT ↓</span></button></section><label className="status-control">Promeni status<select value={s} onChange={e=>setS(e.target.value)}><option>Na čekanju</option><option>Potvrđena</option><option>Aktivna</option><option>Povrat danas</option><option>Završena</option><option>Otkazana</option></select></label>{error&&<div className="form-error">{error}</div>}<button className="primary drawer-action" onClick={save} disabled={saving}>{saving?"Čuvanje…":"Sačuvaj izmene"}</button></aside></div>}
function Calendar({open,newReservation,refresh,overrides}:{open:(b:B)=>void;newReservation:()=>void;refresh:number;overrides:Record<string,string>}){const[mode,setMode]=useState("Mesec");const[cursor,setCursor]=useState(new Date(2026,7,24));const[status,setStatus]=useState("Svi statusi");const[added,setAdded]=useState<Array<B&{date:Date}>>([]);useEffect(()=>{fetch("/api/reservations").then(r=>r.ok?r.json():Promise.reject()).then(data=>setAdded((data.reservations||[]).map((r:{code:string;client:string;vehicle:string;startsAt:string;endsAt:string;price:number;status:string})=>({id:r.code,client:r.client,vehicle:r.vehicle,from:formatDate(r.startsAt),to:formatDate(r.endsAt),price:`${Number(r.price).toLocaleString("sr-RS")} RSD`,status:r.status,date:new Date(r.startsAt)})))).catch(()=>{})},[refresh]);const demo=bookings.map((b,i)=>({...b,status:overrides[b.id]||b.status,date:new Date(2026,7,[24,24,24,25,26][i],[9,11,13,8,10][i])}));const events=[...added,...demo].filter((b,i,a)=>a.findIndex(x=>x.id===b.id)===i).filter(b=>status==="Svi statusi"||b.status===status);const same=(a:Date,b:Date)=>a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate();const move=(direction:number)=>setCursor(d=>{const n=new Date(d);if(mode==="Mesec")n.setMonth(n.getMonth()+direction);else n.setDate(n.getDate()+direction*(mode==="Nedelja"?7:1));return n});const today=()=>setCursor(new Date(2026,7,24));const monthStart=new Date(cursor.getFullYear(),cursor.getMonth(),1);const gridStart=new Date(monthStart);gridStart.setDate(1-((monthStart.getDay()+6)%7));const monthDays=Array.from({length:42},(_,i)=>{const d=new Date(gridStart);d.setDate(gridStart.getDate()+i);return d});const weekStart=new Date(cursor);weekStart.setDate(cursor.getDate()-((cursor.getDay()+6)%7));const weekDays=Array.from({length:7},(_,i)=>{const d=new Date(weekStart);d.setDate(weekStart.getDate()+i);return d});const title=mode==="Mesec"?cursor.toLocaleDateString("sr-Latn-RS",{month:"long",year:"numeric"}):mode==="Nedelja"?`${weekDays[0].toLocaleDateString("sr-Latn-RS",{day:"numeric",month:"short"})} — ${weekDays[6].toLocaleDateString("sr-Latn-RS",{day:"numeric",month:"short",year:"numeric"})}`:cursor.toLocaleDateString("sr-Latn-RS",{weekday:"long",day:"numeric",month:"long",year:"numeric"});const eventButton=(b:B)=><button key={b.id} className={`calendar-event ${tone(b.status)}`} onClick={e=>{e.stopPropagation();open(b)}}><b>{b.from.split("•")[1]||"09:00"}</b> {b.vehicle.replace("Volkswagen ","")} • {b.client.split(" ")[0]}</button>;return <><Head title="Kalendar rezervacija" sub="Planirajte dostupnost flote i raspored preuzimanja." action="Nova rezervacija" onAction={newReservation}/><div className="calendar-toolbar"><div className="segmented">{["Mesec","Nedelja","Dan"].map(x=><button onClick={()=>setMode(x)} className={mode===x?"active":""} key={x}>{x}</button>)}</div><div className="calendar-nav"><button onClick={()=>move(-1)} aria-label="Prethodni period">‹</button><button onClick={today}>Danas</button><button onClick={()=>move(1)} aria-label="Sledeći period">›</button></div><h2>{title}</h2><select value={status} onChange={e=>setStatus(e.target.value)}><option>Svi statusi</option><option>Na čekanju</option><option>Potvrđena</option><option>Aktivna</option><option>Povrat danas</option><option>Završena</option><option>Otkazana</option></select></div>{mode==="Mesec"?<section className="calendar panel"><div className="weekdays">{["PON","UTO","SRE","ČET","PET","SUB","NED"].map(x=><b key={x}>{x}</b>)}</div><div className="calendar-grid">{monthDays.map(d=><div className={`${same(d,new Date(2026,7,24))?"today ":""}${d.getMonth()!==cursor.getMonth()?"outside":""}`} key={d.toISOString()} onClick={()=>{setCursor(d);setMode("Dan")}}><span>{d.getDate()}</span>{events.filter(b=>same(b.date,d)).map(eventButton)}</div>)}</div></section>:mode==="Nedelja"?<section className="panel week-calendar">{weekDays.map(d=><div key={d.toISOString()} className={same(d,new Date(2026,7,24))?"today":""} onClick={()=>{setCursor(d);setMode("Dan")}}><header><b>{d.toLocaleDateString("sr-Latn-RS",{weekday:"short"})}</b><span>{d.getDate()}</span></header><section>{events.filter(b=>same(b.date,d)).map(eventButton)}{!events.some(b=>same(b.date,d))&&<small>Slobodan dan</small>}</section></div>)}</section>:<section className="panel day-calendar"><div className="day-hours">{Array.from({length:12},(_,i)=><span key={i}>{String(i+8).padStart(2,"0")}:00</span>)}</div><div className="day-agenda">{events.filter(b=>same(b.date,cursor)).map(eventButton)}{!events.some(b=>same(b.date,cursor))&&<div className="calendar-empty"><b>Nema rezervacija ovog dana</b><span>Kliknite ispod da kreirate novu rezervaciju.</span></div>}<button className="add-calendar-event" onClick={newReservation}>+ Dodaj rezervaciju za ovaj dan</button></div></section>}<div className="calendar-legend"><button onClick={()=>setStatus("Aktivna")}><Badge s="Aktivna"/></button><button onClick={()=>setStatus("Potvrđena")}><Badge s="Potvrđena"/></button><button onClick={()=>setStatus("Povrat danas")}><Badge s="Povrat danas"/></button><button onClick={()=>setStatus("Svi statusi")}>Prikaži sve</button></div></>}
const demoClients:C[]=[{name:"Miloš Jovanović",email:"milos.jovanovic@gmail.com",city:"Beograd",phone:"+381 64 214 8890",reservations:8,value:324500,status:"Aktivan",notes:"Preferira automatik i preuzimanje na aerodromu."},{name:"Ana Petrović",email:"ana.petrovic@gmail.com",city:"Novi Sad",phone:"+381 63 740 1122",reservations:4,value:188000,status:"Aktivan",notes:"Poslovni klijent. Faktura na kraju najma."},{name:"Nikola Ilić",email:"nikola.ilic@gmail.com",city:"Beograd",phone:"+381 65 992 3014",reservations:12,value:576800,status:"VIP",notes:"Loyalty član. Odobren popust od 10%."},{name:"Jelena Marković",email:"jelena.markovic@gmail.com",city:"Niš",phone:"+381 62 118 7740",reservations:3,value:142400,status:"Aktivan",notes:""},{name:"Stefan Ristić",email:"stefan.ristic@gmail.com",city:"Kragujevac",phone:"+381 64 550 3288",reservations:2,value:78900,status:"Na čekanju",notes:"Potrebna potvrda vozačke dozvole."}];
function Clients(){const[q,setQ]=useState("");const[status,setStatus]=useState("Svi statusi");const[city,setCity]=useState("Svi gradovi");const[more,setMore]=useState(false);const[sortValue,setSortValue]=useState(false);const[added,setAdded]=useState<C[]>([]);const[selected,setSelected]=useState<C|null>(null);const[showAdd,setShowAdd]=useState(false);const[loading,setLoading]=useState(true);const load=()=>{setLoading(true);fetch("/api/clients").then(r=>r.ok?r.json():Promise.reject()).then(data=>setAdded(data.clients||[])).catch(()=>{}).finally(()=>setLoading(false))};useEffect(load,[]);const all=[...added,...demoClients].filter((c,i,a)=>a.findIndex(x=>x.email===c.email)===i);const shown=all.filter(c=>(c.name+c.email+c.phone+c.city).toLowerCase().includes(q.toLowerCase())&&(status==="Svi statusi"||c.status===status)&&(city==="Svi gradovi"||c.city===city)).sort((a,b)=>sortValue?b.value-a.value:0);const clear=()=>{setQ("");setStatus("Svi statusi");setCity("Svi gradovi");setSortValue(false)};return <><Head title="Klijenti" sub="Baza klijenata, dokumenta i istorija najma." action="Novi klijent" onAction={()=>setShowAdd(true)}/><Kpis items={[["Ukupno klijenata","1.248","u bazi","+42","blue"],["Aktivni mesec","186","sa rezervacijom","+11%","green"],["Novi klijenti","42","ovog meseca","+18%","violet"],["Prosečna vrednost","38.400 RSD","po rezervaciji","+2,4%","cyan"],["Loyalty članovi","214","17% baze","+9","amber"],["Zadržavanje","68%","ponovni najam","+3,1%","green"]]} actions={[clear,()=>setStatus("Aktivan"),()=>{setStatus("Svi statusi");setAdded(x=>x)},()=>{setStatus("Svi statusi");setSortValue(true)},()=>setStatus("VIP"),()=>{setStatus("Svi statusi");setSortValue(true)}]}/><section className="panel table-panel"><div className="toolbar"><div className="table-search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Ime, email, telefon ili grad..."/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option>Svi statusi</option><option>Aktivan</option><option>VIP</option><option>Na čekanju</option><option>Neaktivan</option></select><button className={more?"filter-active":""} onClick={()=>setMore(x=>!x)}>Više filtera ☷</button></div>{more&&<div className="advanced-filters"><label>Grad<select value={city} onChange={e=>setCity(e.target.value)}><option>Svi gradovi</option>{[...new Set(all.map(c=>c.city))].map(x=><option key={x}>{x}</option>)}</select></label><label><input type="checkbox" checked={sortValue} onChange={e=>setSortValue(e.target.checked)}/> Najvredniji klijenti prvo</label><button onClick={clear}>Očisti filtere</button></div>}<div className="active-filter-note">Prikazano {shown.length} od {all.length} klijenata</div><div className="table-scroll"><table><thead><tr><th>KLIJENT</th><th>GRAD</th><th>TELEFON</th><th>REZERVACIJE</th><th>UKUPNA VREDNOST</th><th>STATUS</th><th/></tr></thead><tbody>{shown.map(c=><tr key={c.email} onClick={()=>setSelected(c)}><td><div className="person"><span>{c.name.split(" ").map(x=>x[0]).join("")}</span><div><strong>{c.name}</strong><small>{c.email}</small></div></div></td><td>{c.city}</td><td>{c.phone}</td><td><strong>{c.reservations}</strong></td><td><strong>{c.value.toLocaleString("sr-RS")} RSD</strong></td><td><Badge s={c.status}/></td><td><button className="row-action" onClick={e=>{e.stopPropagation();setSelected(c)}}>⋯</button></td></tr>)}</tbody></table>{!loading&&!shown.length&&<div className="empty-table">Nema klijenata koji odgovaraju izabranim filterima.</div>}{loading&&<div className="vehicle-loading">Učitavanje sačuvanih klijenata…</div>}</div></section>{showAdd&&<ClientForm close={()=>setShowAdd(false)} saved={c=>{setAdded(x=>[c,...x]);setShowAdd(false)}}/>}{selected&&<ClientPanel client={selected} close={()=>setSelected(null)} saved={c=>{setAdded(x=>[c,...x.filter(y=>y.email!==selected.email)]);setSelected(c)}}/>}</>}
function ClientForm({close,saved}:{close:()=>void;saved:(c:C)=>void}){const[form,setForm]=useState<C>({name:"",email:"",city:"Beograd",phone:"",reservations:0,value:0,status:"Aktivan",notes:""});const[saving,setSaving]=useState(false);const[error,setError]=useState("");const set=(k:keyof C,v:string|number)=>setForm(f=>({...f,[k]:v}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setSaving(true);setError("");try{const r=await fetch("/api/clients",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(form)});const data=await r.json();if(!r.ok)throw new Error(data.error||"Klijent nije sačuvan.");saved(data.client)}catch(e){setError(e instanceof Error?e.message:"Klijent nije sačuvan.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer add-vehicle" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>NOVI KLIJENT</small><h2>Dodaj klijenta</h2><p className="drawer-intro">Podaci će biti trajno sačuvani u bazi klijenata.</p><form onSubmit={submit}><label>Ime i prezime *<input required value={form.name} onChange={e=>set("name",e.target.value)} placeholder="Petar Petrović"/></label><div className="add-form-grid"><label>Email *<input required type="email" value={form.email} onChange={e=>set("email",e.target.value)} placeholder="petar@email.com"/></label><label>Telefon *<input required value={form.phone} onChange={e=>set("phone",e.target.value)} placeholder="+381 64 123 4567"/></label><label>Grad *<select value={form.city} onChange={e=>set("city",e.target.value)}><option>Beograd</option><option>Novi Sad</option><option>Niš</option><option>Kragujevac</option><option>Subotica</option></select></label><label>Status<select value={form.status} onChange={e=>set("status",e.target.value)}><option>Aktivan</option><option>VIP</option><option>Na čekanju</option><option>Neaktivan</option></select></label></div><label>Napomena<textarea value={form.notes} onChange={e=>set("notes",e.target.value)} placeholder="Preferencije i važne informacije..."/></label>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="outline" onClick={close}>Otkaži</button><button className="primary" disabled={saving}>{saving?"Čuvanje…":"Dodaj klijenta"}</button></div></form></aside></div>}
function ClientPanel({client,close,saved}:{client:C;close:()=>void;saved:(c:C)=>void}){const[tab,setTab]=useState("Pregled");const[edit,setEdit]=useState(false);const[form,setForm]=useState(client);const[saving,setSaving]=useState(false);const[error,setError]=useState("");const set=(k:keyof C,v:string)=>setForm(f=>({...f,[k]:v}));const save=async()=>{setSaving(true);setError("");try{const r=await fetch("/api/clients",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,originalEmail:client.email})});const data=await r.json();if(!r.ok)throw new Error(data.error||"Izmene nisu sačuvane.");saved(data.client);setEdit(false)}catch(e){setError(e instanceof Error?e.message:"Izmene nisu sačuvane.")}finally{setSaving(false)}};const download=(name:string)=>{const url=URL.createObjectURL(new Blob([`DriveNode Fleet Manager\n${name}\nKlijent: ${form.name}\nEmail: ${form.email}\nTelefon: ${form.phone}\nStatus: ${form.status}`],{type:"text/plain;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=`${name.replace(/\s/g,"_")}_${form.name.replace(/\s/g,"_")}.txt`;a.click();URL.revokeObjectURL(url)};return <div className="drawer-wrap" onClick={close}><aside className="drawer client-panel" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>KARTICA KLIJENTA</small><div className="client-hero"><span>{form.name.split(" ").map(x=>x[0]).join("")}</span><div><h2>{form.name}</h2><Badge s={form.status}/></div></div><div className="client-tabs">{["Pregled","Rezervacije","Dokumenta","Napomene"].map(x=><button key={x} className={tab===x?"active":""} onClick={()=>setTab(x)}>{x}</button>)}</div>{tab==="Pregled"&&(edit?<div className="client-edit"><label>Ime i prezime<input value={form.name} onChange={e=>set("name",e.target.value)}/></label><label>Email<input type="email" value={form.email} onChange={e=>set("email",e.target.value)}/></label><label>Telefon<input value={form.phone} onChange={e=>set("phone",e.target.value)}/></label><label>Grad<input value={form.city} onChange={e=>set("city",e.target.value)}/></label><label>Status<select value={form.status} onChange={e=>set("status",e.target.value)}><option>Aktivan</option><option>VIP</option><option>Na čekanju</option><option>Neaktivan</option></select></label>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button className="outline" onClick={()=>setEdit(false)}>Otkaži</button><button className="primary" onClick={save} disabled={saving}>{saving?"Čuvanje…":"Sačuvaj"}</button></div></div>:<><div className="client-contact">{[["Email",form.email],["Telefon",form.phone],["Grad",form.city],["Broj rezervacija",String(form.reservations)],["Ukupna vrednost",`${form.value.toLocaleString("sr-RS")} RSD`]].map(x=><div key={x[0]}><small>{x[0]}</small><b>{x[1]}</b></div>)}</div><button className="primary drawer-action" onClick={()=>setEdit(true)}>Uredi klijenta</button></>)}{tab==="Rezervacije"&&<div className="client-records">{bookings.filter(b=>b.client===form.name).map(b=><button key={b.id}><div><b>{b.id} • {b.vehicle}</b><small>{b.from} — {b.to}</small></div><Badge s={b.status}/></button>)}{!bookings.some(b=>b.client===form.name)&&<div className="empty-table">Klijent još nema rezervacija.</div>}</div>}{tab==="Dokumenta"&&<div className="client-records"><button onClick={()=>download("Lični podaci")}><div><b>□ Lični podaci klijenta</b><small>Ažurirano danas</small></div><span>TXT ↓</span></button><button onClick={()=>download("Vozačka dozvola")}><div><b>□ Podaci vozačke dozvole</b><small>Važeći dokument</small></div><span>TXT ↓</span></button></div>}{tab==="Napomene"&&<div className="client-notes"><textarea value={form.notes} onChange={e=>set("notes",e.target.value)} placeholder="Dodajte napomenu o klijentu..."/><button className="primary" onClick={save} disabled={saving}>{saving?"Čuvanje…":"Sačuvaj napomenu"}</button>{error&&<div className="form-error">{error}</div>}</div>}</aside></div>}
function SimpleTable({headers,rows}:{headers:string[];rows:string[][]}){return <section className="panel table-panel"><div className="table-scroll"><table><thead><tr>{headers.map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((x,j)=><td key={j}>{j===0?<strong>{x}</strong>:j===r.length-1?<Badge s={x}/>:x}</td>)}</tr>)}</tbody></table></div></section>}
