function Reports(){return <><Head title="Izveštaji" sub="Ključni pokazatelji za donošenje boljih poslovnih odluka."/><Kpis items={[["Iskorišćenost flote","78%","cilj 75%","+4,2%","green"],["Prihod po vozilu","118.600 RSD","mesečni prosek","+8,1%","blue"],["Broj rezervacija","284","ovog meseca","+12%","violet"],["Prosečno trajanje","4,6 dana","po najmu","+0,3","cyan"],["Najprofitabilnije","BMW 320d","284.500 RSD","Top 1","amber"],["Ocena klijenata","4,8 / 5","126 recenzija","+0,2","green"]]}/><div className="reports-grid"><section className="panel"><h2>Iskorišćenost flote</h2>{[["Economy",88],["Compact",82],["Premium",74],["SUV",68],["Kombi",61]].map(x=><div className="progress-row" key={x[0]}><span>{x[0]}</span><i><em style={{width:`${x[1]}%`}}/></i><b>{x[1]}%</b></div>)}</section><section className="panel"><h2>Najprofitabilnija vozila</h2>{vehicles.slice(0,5).map((v,i)=><div className="ranking" key={v.plate}><b>0{i+1}</b><span className="car-thumb">▰</span><div><strong>{v.name}</strong><small>{v.plate}</small></div><em>{[284500,241800,219600,194200,176400][i].toLocaleString("sr-RS")} RSD</em></div>)}</section></div></>}
function Users(){return <><Head title="Korisnici i dozvole" sub="Upravljajte timom, ulogama i pristupom podacima." action="Pozovi korisnika"/><SimpleTable headers={["KORISNIK","EMAIL","ULOGA","POSLOVNICA","STATUS"]} rows={[["Marko Nikolić","marko@drivenode.rs","Administrator","Sve poslovnice","Aktivan"],["Jovana Simić","jovana@drivenode.rs","Menadžer","Beograd","Aktivan"],["Luka Pavlović","luka@drivenode.rs","Agent","Novi Sad","Aktivan"],["Milica Stojanović","milica@drivenode.rs","Agent","Niš","Aktivan"],["Aleksandar Vasić","aleksandar@drivenode.rs","Računovođa","Sve poslovnice","Pozvan"]]}/></>}
function Settings(){const[tab,setTab]=useState("Firma");return <><Head title="Podešavanja" sub="Prilagodite DriveNode vašem poslovanju."/><div className="settings-layout"><nav>{["Firma","Poslovnice","Cenovnik","Dodaci","Načini plaćanja","Porezi i valuta","Obaveštenja","Integracije"].map(x=><button className={tab===x?"active":""} onClick={()=>setTab(x)} key={x}>{x}<span>›</span></button>)}</nav><section className="panel settings-form"><h2>{tab}</h2><p>Osnovni podaci i podešavanja modula.</p><div className="form-grid"><label>Naziv kompanije<input defaultValue="DriveNode Rent a Car d.o.o."/></label><label>PIB<input defaultValue="112845931"/></label><label>Matični broj<input defaultValue="21849302"/></label><label>Telefon<input defaultValue="+381 11 440 28 40"/></label><label className="full">Adresa<input defaultValue="Bulevar Mihajla Pupina 10A, 11070 Beograd"/></label><label>Email<input defaultValue="office@drivenode.rs"/></label><label>Web sajt<input defaultValue="www.drivenode.rs"/></label></div><div className="form-actions"><button className="outline">Otkaži</button><button className="primary">Sačuvaj izmene</button></div></section></div></>}
function Login({on}:{on:()=>void}){return <div className="login"><section className="login-brand"><div className="brand"><span className="brand-mark">D</span><div><b>DriveNode</b><small>FLEET MANAGER</small></div></div><div><span className="login-pill">DNFM BETA V1</span><h1>Vaša flota.<br/><em>Potpuna kontrola.</em></h1><p>Jednostavnije rezervacije, bolja iskorišćenost i više profita — sve na jednom mestu.</p><div className="login-metrics"><div><b>24</b><small>vozila</small></div><div><b>78%</b><small>iskorišćenost</small></div><div><b>+12,8%</b><small>rast prihoda</small></div></div></div></section><section className="login-form"><form onSubmit={e=>{e.preventDefault();on()}}><div className="login-logo"><span className="brand-mark">D</span></div><h2>Dobro došli nazad</h2><p>Prijavite se na vaš DriveNode nalog.</p><label>Email adresa<input type="email" defaultValue="marko@drivenode.rs"/></label><label>Lozinka<input type="password" defaultValue="drivenode"/></label><div className="remember"><label><input type="checkbox" defaultChecked/> Zapamti me</label><a>Zaboravili ste lozinku?</a></div><button className="primary login-button">Prijavi se</button><small>Demo pristup je unapred popunjen</small></form></section></div>}
export default function Home(){const[logged,setLogged]=useState(false);const[page,setPage]=useState("Pregled");const[v,setV]=useState<V|null>(null);const[b,setB]=useState<B|null>(null);const[newBooking,setNewBooking]=useState(false);const[bookingReturnPage,setBookingReturnPage]=useState("Rezervacije");const[bookingRefresh,setBookingRefresh]=useState(0);const[bookingOverrides,setBookingOverrides]=useState<Record<string,string>>({});const[vehicleAddTrigger,setVehicleAddTrigger]=useState(0);const[q,setQ]=useState("");if(!logged)return <Login on={()=>setLogged(true)}/>;const go=(x:string)=>{setPage(x);setV(null)};const createBooking=()=>{setBookingReturnPage(page);setNewBooking(true)};const addVehicle=()=>{setV(null);setPage("Vozila");setVehicleAddTrigger(x=>x+1)};const bookingSaved=()=>{setNewBooking(false);setPage(bookingReturnPage);setBookingRefresh(x=>x+1)};const statusSaved=(id:string,status:string)=>{setBookingOverrides(x=>({...x,[id]:status}));setBookingRefresh(x=>x+1);setB(null)};let c:React.ReactNode;if(v)c=<VehicleDetail v={v} back={()=>setV(null)}/>;else c=page==="Vozila"?<Vehicles open={setV} addTrigger={vehicleAddTrigger}/>:page==="Rezervacije"?<Reservations open={setB} newReservation={createBooking} refresh={bookingRefresh} overrides={bookingOverrides}/>:page==="Kalendar"?<Calendar open={setB} newReservation={createBooking} refresh={bookingRefresh} overrides={bookingOverrides}/>:page==="Klijenti"?<Clients/>:page.startsWith("Servisi")?<Services/>:page==="Finansije"?<Finance/>:page==="Dokumentacija"?<Documents/>:page==="Izveštaji"?<Reports/>:page.startsWith("Korisnici")?<Users/>:page==="Podešavanja"?<Settings/>:<Dashboard go={go} openBooking={setB} newReservation={createBooking} addVehicle={addVehicle}/>;const hits=q?[...vehicles.map(x=>[x.name,x.plate,()=>{setV(x);setQ("")} ]),...bookings.map(x=>[x.client,x.id,()=>{setB({...x,status:bookingOverrides[x.id]||x.status});setQ("")}])].filter(x=>(x[0]+" "+x[1]).toLowerCase().includes(q.toLowerCase())).slice(0,5):[];return <main className="app-shell"><aside className="sidebar"><div className="brand"><span className="brand-mark">D</span><div><b>DriveNode</b><small>FLEET MANAGER</small></div></div><nav>{nav.map((x,i)=><button key={x} className={page===x&&!v?"active":""} onClick={()=>go(x)}><span className="nav-icon">{["◈","▣","▤","▦","◉","⚙","◎","□","◩","◌"][i]}</span>{x}{x.startsWith("Servisi")&&<em>3</em>}</button>)}</nav><div className="sidebar-bottom"><button onClick={()=>go("Podešavanja")}><span className="nav-icon">⚙</span>Podešavanja</button><div className="profile"><span>MN</span><div><b>Marko Nikolić</b><small>Administrator</small></div><i onClick={()=>setLogged(false)}>⋯</i></div></div></aside><section className="content"><header><div className="search"><span>⌕</span><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Pretraži vozila, rezervacije, klijente..."/><kbd>⌘ K</kbd>{hits.length>0&&<div className="search-results">{hits.map((x,i)=><button key={i} onClick={x[2] as ()=>void}><b>{x[0] as string}</b><small>{x[1] as string}</small></button>)}</div>}</div><div className="head-actions"><button onClick={()=>go("Servisi i registracije")} aria-label="Otvori obaveštenja">○<span className="dot"/></button><button className="primary" onClick={createBooking}>+ Nova rezervacija</button></div></header><div className="page">{c}</div></section>{b&&<BookingPanel b={b} close={()=>setB(null)} saved={statusSaved}/>} {newBooking&&<NewReservationModal close={()=>setNewBooking(false)} saved={bookingSaved}/>}</main>}
